function hill(x,z,rx,ry,rz,shade){
  const geo=new THREE.SphereGeometry(1,12,6,0,TAU,0,Math.PI/2);
  const mesh=createMesh(geo,mat(shade),island,x,.565,z);
  mesh.scale.set(rx,ry,rz);
  return mesh;
}
